#!/usr/bin/python3
"""fleet-inventory coverage counts add up (generated by package-inventory.org). The collectors are replaced by fakes; nothing on the host is read except os-release and ss."""
import importlib.machinery, importlib.util, os, unittest

HERE = os.path.dirname(os.path.abspath(__file__))
PATH = next(p for p in (os.path.join(HERE, '..', 'bin', 'fleet-inventory'), os.path.join(HERE, 'fleet-inventory')) if os.path.isfile(p))
spec = importlib.util.spec_from_loader('fi', importlib.machinery.SourceFileLoader('fi', PATH)); fi = importlib.util.module_from_spec(spec); spec.loader.exec_module(fi)


def row(eco, name, ver='1', **k):
    return dict(eco=eco, name=name, version=ver, **k)


class Coverage(unittest.TestCase):
    def collect(self, fakes):
        saved = {n: getattr(fi, n) for n in ('c_dpkg', 'c_rpm', 'c_python', 'c_npm', 'c_cargo', 'c_docker', 'c_flatpak', 'c_snap', 'c_guix', 'surfaces', 'walk_dirs')}
        try:
            for n in ('c_dpkg', 'c_rpm', 'c_cargo', 'c_docker', 'c_flatpak', 'c_snap', 'c_guix'):
                setattr(fi, n, fakes.get(n, lambda: ([], 'ok', '')))
            fi.c_python = fakes.get('c_python', lambda walked: ([], 'ok', ''))
            fi.c_npm = fakes.get('c_npm', lambda walked: ([], 'ok', ''))
            fi.surfaces = lambda: ([dict(proto='tcp', port=1, scope='loopback', process='x')], 'ok', '')
            fi.walk_dirs = lambda: iter(())
            return fi.collect()
        finally:
            for n, f in saved.items(): setattr(fi, n, f)

    def test_the_counts_add_up_to_the_items_even_when_a_collector_repeats_itself(self):
        npm = [row('npm', 'a', where='~/x'), row('npm', 'a', where='~/x'), row('npm', 'b', where='~/y')]   # one duplicate row
        d = self.collect({'c_npm': lambda walked: (npm, 'ok', ''), 'c_dpkg': lambda: ([row('deb', 'p')], 'ok', '')})
        cov = d['coverage']
        self.assertEqual((cov['npm']['count'], cov['npm']['scanned']), (2, 3))
        self.assertEqual(sum(v['count'] for k, v in cov.items() if k != 'listening'), len(d['items']))

    def test_a_row_found_by_two_collectors_is_counted_once_for_the_first(self):
        same = row('PyPI', 'z', where='~/s')
        d = self.collect({'c_dpkg': lambda: ([same], 'ok', ''), 'c_python': lambda walked: ([same, row('PyPI', 'q', where='~/s')], 'ok', '')})
        cov = d['coverage']
        self.assertEqual((cov['dpkg']['count'], cov['python']['count'], cov['python']['scanned']), (1, 1, 2))
        self.assertEqual(sum(v['count'] for k, v in cov.items() if k != 'listening'), len(d['items']))

    def test_coverage_never_changes_the_digest(self):
        a = self.collect({'c_npm': lambda walked: ([row('npm', 'a', where='w')], 'ok', '')})
        b = self.collect({'c_npm': lambda walked: ([row('npm', 'a', where='w'), row('npm', 'a', where='w')], 'ok', '')})
        self.assertEqual(a['digest'], b['digest'])
        self.assertNotEqual(a['coverage']['npm']['scanned'], b['coverage']['npm']['scanned'])

    def test_listening_counts_surfaces_not_items(self):
        d = self.collect({}); self.assertEqual(d['coverage']['listening']['count'], 1); self.assertEqual(len(d['items']), 1)  # only the kernel row


if __name__ == '__main__':
    unittest.main(verbosity=2)
